npc {
  map = "payon_in01", x = 84, y = 26, dir = 4, sprite = 88, name = "Miner",
  src = "817:other/refine.txt:40",
  on_click = function()
    local c
    mes "[Miner]"
    mes "Hello, Im selling metals I just mined."
    mes "They are Pharacon and Emvertacon."
    mes "Would you like to buy some?"
    c = menu("Pharacon - 200z", "Emveretarcon - 1000z")
    if c == 1 then goto PHARA elseif c == 2 then goto EMVER end
    ::PHARA::
    tmp.itemid = 1010
    tmp.value = 200
    goto CONTINUE
    ::EMVER::
    tmp.itemid = 1011
    tmp.value = 1000
    ::CONTINUE::
    tmp.ammount = input_number()
    if tmp.ammount <= 0 then goto BELOW end
    if player.zeny < (tmp.value * tmp.ammount) then goto NO end
    if check_weight(tmp.item, tmp.amount) == 0 then goto FAIL end
    give_item(tmp.itemid, tmp.ammount)
    player.zeny = player.zeny - (tmp.value * tmp.ammount)
    close()
    do return end
    ::NO::
    mes "You do not have enough zeny!"
    close()
    do return end
    ::FAIL::
    mes "You cant hold that many of that item"
    close()
    do return end
    ::BELOW::
    mes "You have to buy a POSITIVE amount of items!"
    close()
  end,
}

